fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let pal = [0xff4455, 0x44cc66, 0x4477ff, 0xffcc22, 0xcc55ee, 0x22cccc];
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 1);
        host::display::state_set(2, 120);
        host::display::state_set(3, 0);
        host::display::state_set(4, 3);
        host::display::state_set(5, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(6) == 0;
    host::display::state_set(6, down);
    if host::display::state_get(5) == 1 {
        host::display::clear(0x101018);
        host::display::draw_string(120, 180, "COLOR BLIND", 0xff4040, 4);
        host::display::draw_string(140, 250, "MATCHED", 0x808080, 2);
        host::display::draw_number(300, 244, host::display::state_get(3), 0xffffff, 3);
        host::display::draw_string(140, 320, "TAP TO RESTART", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let round: i32 = host::display::state_get(1);
        let target: i32 = hash(round * 17) % 6;
        let cpos: i32 = hash(round * 7) % 3;
        let o1: i32 = 1 + hash(round * 3) % 5;
        let mut o2: i32 = 1 + hash(round * 5) % 5;
        if o2 == o1 { o2 = (o1 % 5) + 1; }
        let mut timer: i32 = host::display::state_get(2) - 1;
        let mut wrong: i32 = 0;
        let mut next: i32 = 0;
        if timer <= 0 { wrong = 1; }
        if tap {
            let px: i32 = host::display::pointer_x();
            let py: i32 = host::display::pointer_y();
            if py >= 300 && py < 390 && px >= 30 {
                let b: i32 = (px - 30) / 155;
                if b >= 0 && b < 3 && px - 30 - b * 155 < 140 {
                    if b == cpos {
                        host::display::state_set(3, host::display::state_get(3) + 1);
                        next = 1;
                    } else {
                        wrong = 1;
                    }
                }
            }
        }
        if wrong == 1 {
            let lives: i32 = host::display::state_get(4) - 1;
            host::display::state_set(4, lives);
            if lives <= 0 { host::display::state_set(5, 1); }
            next = 1;
        }
        if next == 1 {
            host::display::state_set(1, round + 1);
            timer = 120;
        }
        host::display::state_set(2, timer);
        host::display::clear(0x14141c);
        host::display::draw_string(60, 60, "TAP THE SWATCH NAMED", 0x808080, 2);
        match target {
            0 => { host::display::draw_string(200, 120, "RED", 0xffffff, 5); }
            1 => { host::display::draw_string(170, 120, "GREEN", 0xffffff, 5); }
            2 => { host::display::draw_string(180, 120, "BLUE", 0xffffff, 5); }
            3 => { host::display::draw_string(180, 120, "GOLD", 0xffffff, 5); }
            4 => { host::display::draw_string(180, 120, "PINK", 0xffffff, 5); }
            _ => { host::display::draw_string(180, 120, "TEAL", 0xffffff, 5); }
        }
        let mut b2: i32 = 0;
        while b2 < 3 {
            let mut ci: i32 = target;
            if b2 != cpos {
                if b2 == (cpos + 1) % 3 {
                    ci = (target + o1) % 6;
                } else {
                    ci = (target + o2) % 6;
                }
            }
            host::display::fill_rect(30 + b2 * 155, 300, 140, 90, pal[ci]);
            b2 = b2 + 1;
        }
        host::display::fill_rect(0, h - 14, timer * w / 120, 8, 0xffffff);
        let mut miss: i32 = 3 - host::display::state_get(4);
        let mut k: i32 = 0;
        while k < miss {
            host::display::draw_char(w - 30 - k * 26, 20, 88, 0xff4455, 3);
            k = k + 1;
        }
        host::display::draw_number(16, 20, host::display::state_get(3), 0xffffff, 3);
    }
    host::display::present();
}
